pragma solidity 0.8.28;

import {IMorpho} from "morpho-blue/interfaces/IMorpho.sol";
import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Initializable} from "@openzeppelin/contracts/proxy/utils/Initializable.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts/proxy/utils/UUPSUpgradeable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IVaultV2} from "vault-v2/interfaces/IVaultV2.sol";
import {IBox} from "./interfaces/IBox.sol";
import {IFunding} from "./interfaces/IFunding.sol";
import {ISwapper} from "./interfaces/ISwapper.sol";
import {ErrorsLib} from "./libraries/ErrorsLib.sol";

/// @notice Callback interface for Morpho flash loans
interface IMorphoFlashLoanCallback {
    function onMorphoFlashLoan(uint256 assets, bytes calldata data) external;
}

/// @notice Callback interface for Box flash loans
interface IBoxFlashCallback {
    function onBoxFlash(IERC20 token, uint256 amount, bytes calldata data) external;
}

/// @notice Interface for skimmable adapters
interface ISkimmableAdapter {
    function skim(address token) external;
}

/// @notice Result struct for swap operations with slippage tracking
struct SwapResult {
    uint256 expected;
    uint256 received;
    uint256 slippageBefore;
    uint256 slippageAfter;
}

/**
 * @title VaultV2Allocator
 * @notice Helper contract for VaultV2 and Box allocations with flash loan support
 * @dev Upgradeable via UUPS pattern. Operators can perform complex allocation operations
 *      including leverage, deleverage, and refinancing with optional collateral/loan swaps.
 */
contract VaultV2Allocator is Initializable, UUPSUpgradeable, AccessControl, IMorphoFlashLoanCallback, IBoxFlashCallback {
    using SafeERC20 for IERC20;

    // =========================================================================
    //                              Constants
    // =========================================================================

    /// @notice Role for operators allowed to perform restricted actions.
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");

    // =========================================================================
    //                           Transient Storage
    // =========================================================================

    /// @dev Morpho address for flash loan callback validation
    address internal transient _morpho;

    /// @dev Box address for flash callback validation
    address internal transient _box;

    /// @dev Expected amount from last swap
    uint256 internal transient _expected;

    /// @dev Received amount from last swap
    uint256 internal transient _received;

    /// @dev Accumulated slippage before operation
    uint256 internal transient _slippageBefore;

    /// @dev Accumulated slippage after operation
    uint256 internal transient _slippageAfter;

    // =========================================================================
    //                              Constructor
    // =========================================================================

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    // =========================================================================
    //                              Initializer
    // =========================================================================

    /**
     * @notice Initializes the contract, setting up access control and UUPS upgradeability.
     * @param initialAdmin The address to grant initial admin and operator roles.
     */
    function initialize(address initialAdmin) public initializer {
        _grantRole(DEFAULT_ADMIN_ROLE, initialAdmin);
        _grantRole(OPERATOR_ROLE, initialAdmin);
    }

    // =========================================================================
    //                              Modifiers
    // =========================================================================

    /**
     * @notice Restricts execution to OPERATOR_ROLE or DEFAULT_ADMIN_ROLE.
     */
    modifier onlyOperator() {
        _requireOperatorRole();
        _;
    }

    modifier onlyAdmin() {
        _requireAdminRole();
        _;
    }

    function _requireOperatorRole() internal view {
        address sender = _msgSender();
        require(hasRole(OPERATOR_ROLE, sender) || hasRole(DEFAULT_ADMIN_ROLE, sender), "VaultV2Allocator: Caller is not an operator");
    }

    function _requireAdminRole() internal view {
        require(hasRole(DEFAULT_ADMIN_ROLE, _msgSender()), "VaultV2Allocator: Caller is not an admin");
    }

    // =========================================================================
    //                        Admin & Configuration
    // =========================================================================

    /**
     * @notice Authorizes an upgrade to a new implementation.
     * @dev Only callable by DEFAULT_ADMIN_ROLE. Part of OpenZeppelin UUPS pattern.
     * @param newImplementation The address of the new implementation contract.
     */
    function _authorizeUpgrade(address newImplementation) internal override onlyAdmin {}

    /**
     * @notice Grants or revokes the OPERATOR_ROLE.
     * @dev Only callable by DEFAULT_ADMIN_ROLE.
     * @param operator The address to grant or revoke the role from.
     * @param grant True to grant the role, false to revoke it.
     */
    function setOperatorRole(address operator, bool grant) external onlyAdmin {
        if (grant) {
            _grantRole(OPERATOR_ROLE, operator);
        } else {
            _revokeRole(OPERATOR_ROLE, operator);
        }
    }

    // =========================================================================
    //                        Simple Vault Operations
    // =========================================================================

    /**
     * @notice Allocates funds from a VaultV2 to an adapter.
     * @param vault The VaultV2 to allocate from.
     * @param adapter The adapter to allocate to.
     * @param amount The amount to allocate.
     */
    function allocateVault(IVaultV2 vault, address adapter, uint256 amount) external onlyOperator {
        vault.allocate(adapter, "", amount);
    }

    /**
     * @notice Deallocates funds from a VaultV2 adapter.
     * @param vault The VaultV2 to deallocate from.
     * @param adapter The adapter to deallocate from.
     * @param amount The amount to deallocate.
     */
    function deallocateVault(IVaultV2 vault, address adapter, uint256 amount) external onlyOperator {
        vault.deallocate(adapter, "", amount);
    }

    /**
     * @notice Deallocates funds from a VaultV2 adapter using explicit adapter data.
     * @param vault The VaultV2 to deallocate from.
     * @param adapter The adapter to deallocate from.
     * @param data The adapter-specific data for the deallocation.
     * @param amount The amount to deallocate.
     */
    function deallocateVaultWithData(IVaultV2 vault, address adapter, bytes memory data, uint256 amount) external onlyOperator {
        vault.deallocate(adapter, data, amount);
    }

    /**
     * @notice Reallocates funds between two VaultV2 adapters using explicit adapter data.
     * @param vault The VaultV2 to rebalance within.
     * @param fromAdapter The adapter to deallocate from.
     * @param fromData The adapter-specific data for the source deallocation.
     * @param toAdapter The adapter to allocate to.
     * @param toData The adapter-specific data for the destination allocation.
     * @param amount The amount to move.
     */
    function reallocateVault(
        IVaultV2 vault,
        address fromAdapter,
        bytes memory fromData,
        address toAdapter,
        bytes memory toData,
        uint256 amount
    ) external onlyOperator {
        vault.deallocate(fromAdapter, fromData, amount);
        vault.allocate(toAdapter, toData, amount);
    }

    /**
     * @notice Returns how much of a token can currently be skimmed from an adapter.
     * @param adapter The adapter to inspect.
     * @param token The token to inspect.
     * @return amount The current balance of `token` held by `adapter`.
     */
    function skimmableBalance(address adapter, IERC20 token) external view returns (uint256 amount) {
        amount = token.balanceOf(adapter);
    }

    /**
     * @notice Skims a token from an adapter, swaps it to the vault asset, and donates the proceeds to the vault.
     * @param vault The VaultV2 receiving the donated assets.
     * @param adapter The adapter to skim from.
     * @param skimToken The token to skim and optionally swap.
     * @param swapper The swapper to convert skimToken to the vault asset.
     * @param swapData The swap data for the swapper.
     * @param minExpected The minimum expected amount of vault assets to donate.
     * @return result The swap result with expected, received, and slippage tracking.
     */
    function reinvestSkimAdapter(
        IVaultV2 vault,
        address adapter,
        IERC20 skimToken,
        ISwapper swapper,
        bytes memory swapData,
        uint256 minExpected
    ) external onlyOperator returns (SwapResult memory result) {
        IERC20 asset = IERC20(vault.asset());
        uint256 skimTokenBalanceBefore = skimToken.balanceOf(address(this));
        uint256 assetBalanceBefore = asset.balanceOf(address(this));

        ISkimmableAdapter(adapter).skim(address(skimToken));

        uint256 skimmed = skimToken.balanceOf(address(this)) - skimTokenBalanceBefore;
        require(skimmed > 0, "VaultV2Allocator.reinvestSkimAdapter: No tokens skimmed");

        if (address(skimToken) != address(asset)) {
            skimToken.forceApprove(address(swapper), skimmed);
            swapper.sell(skimToken, asset, skimmed, swapData);
            skimToken.forceApprove(address(swapper), 0);
        }

        result.received = asset.balanceOf(address(this)) - assetBalanceBefore;
        result.expected = result.received;

        require(result.received >= minExpected, "VaultV2Allocator.reinvestSkimAdapter: Received less than min expected");

        asset.safeTransfer(address(vault), result.received);
    }

    // =========================================================================
    //                        Simple Box Operations
    // =========================================================================

    /**
     * @notice Allocates base asset to a token in the Box.
     * @param box The Box to allocate in.
     * @param toToken The token to allocate to.
     * @param amount The amount of base asset to allocate.
     * @param swapper The swapper contract to use.
     * @param swapData The swap data for the swapper.
     * @param minExpected The minimum expected amount of tokens to receive.
     * @return result The swap result with expected, received, and slippage tracking.
     */
    function allocateBox(
        IBox box,
        IERC20 toToken,
        uint256 amount,
        ISwapper swapper,
        bytes memory swapData,
        uint256 minExpected
    ) external onlyOperator returns (SwapResult memory result) {
        result.slippageBefore = box.accumulatedSlippage();

        (result.expected, result.received) = box.allocate(toToken, amount, swapper, swapData);

        result.slippageAfter = box.accumulatedSlippage();

        require(result.received >= minExpected, "VaultV2Allocator.allocateBox: Received less than min expected");
    }

    /**
     * @notice Deallocates a token back to base asset in the Box.
     * @param box The Box to deallocate from.
     * @param fromToken The token to deallocate.
     * @param amount The amount of tokens to deallocate.
     * @param swapper The swapper contract to use.
     * @param swapData The swap data for the swapper.
     * @param minExpected The minimum expected amount of base asset to receive.
     * @return result The swap result with expected, received, and slippage tracking.
     */
    function deallocateBox(
        IBox box,
        IERC20 fromToken,
        uint256 amount,
        ISwapper swapper,
        bytes memory swapData,
        uint256 minExpected
    ) external onlyOperator returns (SwapResult memory result) {
        result.slippageBefore = box.accumulatedSlippage();

        (result.expected, result.received) = box.deallocate(fromToken, amount, swapper, swapData);

        result.slippageAfter = box.accumulatedSlippage();

        require(result.received >= minExpected, "VaultV2Allocator.deallocateBox: Received less than min expected");
    }

    /**
     * @notice Reallocates from one token to another in the Box.
     * @param box The Box to reallocate in.
     * @param fromToken The token to reallocate from.
     * @param toToken The token to reallocate to.
     * @param amount The amount of fromToken to reallocate.
     * @param swapper The swapper contract to use.
     * @param swapData The swap data for the swapper.
     * @param minExpected The minimum expected amount of toToken to receive.
     * @return result The swap result with expected, received, and slippage tracking.
     */
    function reallocateBox(
        IBox box,
        IERC20 fromToken,
        IERC20 toToken,
        uint256 amount,
        ISwapper swapper,
        bytes memory swapData,
        uint256 minExpected
    ) external onlyOperator returns (SwapResult memory result) {
        result.slippageBefore = box.accumulatedSlippage();

        (result.expected, result.received) = box.reallocate(fromToken, toToken, amount, swapper, swapData);

        result.slippageAfter = box.accumulatedSlippage();

        require(result.received >= minExpected, "VaultV2Allocator.reallocateBox: Received less than min expected");
    }

    // =========================================================================
    //                        Box Funding Operations
    // =========================================================================

    /**
     * @notice Pledges collateral to a funding module via the Box.
     */
    function pledgeBox(
        IBox box,
        IFunding fundingModule,
        bytes memory facilityData,
        IERC20 collateralToken,
        uint256 collateralAmount
    ) external onlyOperator {
        box.pledge(fundingModule, facilityData, collateralToken, collateralAmount);
    }

    /**
     * @notice Depledges collateral from a funding module via the Box.
     */
    function depledgeBox(
        IBox box,
        IFunding fundingModule,
        bytes memory facilityData,
        IERC20 collateralToken,
        uint256 collateralAmount
    ) external onlyOperator {
        box.depledge(fundingModule, facilityData, collateralToken, collateralAmount);
    }

    /**
     * @notice Borrows from a funding module via the Box.
     */
    function borrowBox(
        IBox box,
        IFunding fundingModule,
        bytes memory facilityData,
        IERC20 borrowToken,
        uint256 borrowAmount
    ) external onlyOperator {
        box.borrow(fundingModule, facilityData, borrowToken, borrowAmount);
    }

    /**
     * @notice Repays debt to a funding module via the Box.
     */
    function repayBox(
        IBox box,
        IFunding fundingModule,
        bytes memory facilityData,
        IERC20 debtToken,
        uint256 repayAmount
    ) external onlyOperator {
        box.repay(fundingModule, facilityData, debtToken, repayAmount);
    }

    // =========================================================================
    //                    Combined Vault + Box Operations
    // =========================================================================

    /**
     * @notice Allocates from VaultV2 through Box to a token.
     * @dev Handles liquidity sourcing from both Box and Vault.
     */
    function allocateToken(
        IVaultV2 vault,
        address adapter,
        IBox box,
        IERC20 toToken,
        uint256 amount,
        ISwapper swapper,
        bytes memory swapData,
        uint256 minExpected
    ) external onlyOperator returns (SwapResult memory result) {
        IERC20 currency = IERC20(vault.asset());

        uint256 boxLiquidity = currency.balanceOf(address(box));
        uint256 vaultLiquidity = currency.balanceOf(address(vault));
        uint256 neededFromVault = amount > boxLiquidity ? amount - boxLiquidity : 0;

        if (neededFromVault > 0) {
            uint256 availableLiquidity = boxLiquidity + vaultLiquidity;
            uint256 missingLiquidity = amount > availableLiquidity ? amount - availableLiquidity : 0;

            // If there's not enough liquidity in the box + vault, deallocate from the liquidity adapter
            address liquidityAdapter = vault.liquidityAdapter();
            if (missingLiquidity > 0 && liquidityAdapter != address(0)) {
                vault.deallocate(liquidityAdapter, vault.liquidityData(), missingLiquidity);
            }

            vault.allocate(adapter, "", neededFromVault);
        }

        result.slippageBefore = box.accumulatedSlippage();

        (result.expected, result.received) = box.allocate(toToken, amount, swapper, swapData);

        result.slippageAfter = box.accumulatedSlippage();

        require(result.received >= minExpected, "VaultV2Allocator.allocateToken: Received less than min expected");
    }

    /**
     * @notice Deallocates a token from Box back to VaultV2.
     */
    function deallocateToken(
        IVaultV2 vault,
        address adapter,
        IBox box,
        IERC20 fromToken,
        uint256 amount,
        ISwapper swapper,
        bytes memory swapData,
        uint256 minExpected
    ) external onlyOperator returns (SwapResult memory result) {
        result.slippageBefore = box.accumulatedSlippage();

        (result.expected, result.received) = box.deallocate(fromToken, amount, swapper, swapData);

        result.slippageAfter = box.accumulatedSlippage();

        require(result.received >= minExpected, "VaultV2Allocator.deallocateToken: Received less than min expected");

        vault.deallocate(adapter, "", result.received);

        address liquidityAdapter = vault.liquidityAdapter();
        if (liquidityAdapter != address(0)) {
            vault.allocate(liquidityAdapter, vault.liquidityData(), result.received);
        }
    }

    // =========================================================================
    //                     Flash Loan Operations (Leverage)
    // =========================================================================

    /**
     * @notice Leverages a position using a Morpho flash loan.
     * @dev Flow: Flash loan -> Swap loan to collateral -> Pledge collateral -> Borrow to repay flash loan
     * @param morpho The Morpho protocol address for flash loans.
     * @param box The Box to perform operations on.
     * @param fundingModule The funding module to use.
     * @param facilityData The facility data for the funding module.
     * @param swapper The swapper for loan-to-collateral conversion.
     * @param swapData The swap data for the swapper.
     * @param collateralToken The collateral token to acquire.
     * @param loanToken The loan token to flash loan and borrow.
     * @param loanAmount The amount to flash loan/borrow.
     * @return result The swap result with expected, received, and slippage tracking.
     */
    function leverage(
        IMorpho morpho,
        IBox box,
        IFunding fundingModule,
        bytes calldata facilityData,
        ISwapper swapper,
        bytes calldata swapData,
        IERC20 collateralToken,
        IERC20 loanToken,
        uint256 loanAmount
    ) external onlyOperator returns (SwapResult memory result) {
        _morpho = address(morpho);
        _box = address(box);
        _slippageBefore = box.accumulatedSlippage();

        morpho.flashLoan(
            address(loanToken),
            loanAmount,
            abi.encode(
                VaultV2Allocator.leverage.selector,
                address(box),
                fundingModule,
                facilityData,
                collateralToken,
                loanToken,
                loanAmount,
                swapper,
                swapData
            )
        );

        result.expected = _expected;
        result.received = _received;
        result.slippageBefore = _slippageBefore;
        result.slippageAfter = box.accumulatedSlippage();
    }

    /**
     * @notice Deleverages a position using a Morpho flash loan.
     * @dev Flow: Flash loan -> Repay debt -> Depledge collateral -> Swap collateral to loan to repay flash
     * @param morpho The Morpho protocol address for flash loans.
     * @param box The Box to perform operations on.
     * @param fundingModule The funding module to use.
     * @param facilityData The facility data for the funding module.
     * @param swapper The swapper for collateral-to-loan conversion.
     * @param swapData The swap data for the swapper.
     * @param collateralToken The collateral token to withdraw.
     * @param collateralAmount The amount of collateral to withdraw (type(uint256).max for all).
     * @param loanToken The loan token to repay.
     * @param loanAmount The amount of debt to repay (type(uint256).max for all).
     * @return result The swap result with expected, received, and slippage tracking.
     */
    function deleverage(
        IMorpho morpho,
        IBox box,
        IFunding fundingModule,
        bytes calldata facilityData,
        ISwapper swapper,
        bytes calldata swapData,
        IERC20 collateralToken,
        uint256 collateralAmount,
        IERC20 loanToken,
        uint256 loanAmount
    ) external onlyOperator returns (SwapResult memory result) {
        _morpho = address(morpho);
        _box = address(box);
        _slippageBefore = box.accumulatedSlippage();

        if (loanAmount == type(uint256).max) {
            loanAmount = fundingModule.debtBalance(facilityData, loanToken);
        }

        morpho.flashLoan(
            address(loanToken),
            loanAmount,
            abi.encode(
                VaultV2Allocator.deleverage.selector,
                address(box),
                fundingModule,
                facilityData,
                collateralToken,
                collateralAmount,
                loanToken,
                loanAmount,
                swapper,
                swapData
            )
        );

        result.expected = _expected;
        result.received = _received;
        result.slippageBefore = _slippageBefore;
        result.slippageAfter = box.accumulatedSlippage();
    }

    /**
     * @notice Refinances a position to a new facility (same collateral and loan).
     * @dev Flow: Flash loan -> Repay old debt -> Depledge -> Pledge to new -> Borrow from new to repay flash
     * @param morpho The Morpho protocol address for flash loans.
     * @param box The Box to perform operations on.
     * @param fromFundingModule The funding module to refinance from.
     * @param fromFacilityData The facility data for the source.
     * @param toFundingModule The funding module to refinance to.
     * @param toFacilityData The facility data for the destination.
     * @param collateralToken The collateral token.
     * @param collateralAmount The amount of collateral (type(uint256).max for all).
     * @param loanToken The loan token.
     * @param loanAmount The amount of debt (type(uint256).max for all).
     */
    function refinance(
        IMorpho morpho,
        IBox box,
        IFunding fromFundingModule,
        bytes calldata fromFacilityData,
        IFunding toFundingModule,
        bytes calldata toFacilityData,
        IERC20 collateralToken,
        uint256 collateralAmount,
        IERC20 loanToken,
        uint256 loanAmount
    ) external onlyOperator {
        _morpho = address(morpho);
        _box = address(box);

        if (loanAmount == type(uint256).max) {
            loanAmount = fromFundingModule.debtBalance(fromFacilityData, loanToken);
        }
        if (collateralAmount == type(uint256).max) {
            collateralAmount = fromFundingModule.collateralBalance(fromFacilityData, collateralToken);
        }

        morpho.flashLoan(
            address(loanToken),
            loanAmount,
            abi.encode(
                VaultV2Allocator.refinance.selector,
                address(box),
                fromFundingModule,
                fromFacilityData,
                toFundingModule,
                toFacilityData,
                collateralToken,
                collateralAmount,
                loanToken,
                loanAmount
            )
        );
    }

    /**
     * @notice Refinances to a new facility while swapping collateral to a new type.
     * @dev Flow: Flash loan -> Repay old debt -> Depledge old collateral -> Swap to new collateral
     *            -> Pledge new collateral to new facility -> Borrow to repay flash loan
     * @param morpho The Morpho protocol address for flash loans.
     * @param box The Box to perform operations on.
     * @param fromFundingModule The funding module to refinance from.
     * @param fromFacilityData The facility data for the source.
     * @param toFundingModule The funding module to refinance to.
     * @param toFacilityData The facility data for the destination.
     * @param fromCollateralToken The original collateral token.
     * @param fromCollateralAmount The amount of original collateral (type(uint256).max for all).
     * @param toCollateralToken The new collateral token.
     * @param loanToken The loan token (same for both facilities).
     * @param loanAmount The amount of debt (type(uint256).max for all).
     * @param swapper The swapper for collateral conversion.
     * @param swapData The swap data for the swapper.
     * @return result The swap result with expected, received, and slippage tracking.
     */
    function refinanceSwapCollateral(
        IMorpho morpho,
        IBox box,
        IFunding fromFundingModule,
        bytes memory fromFacilityData,
        IFunding toFundingModule,
        bytes memory toFacilityData,
        IERC20 fromCollateralToken,
        uint256 fromCollateralAmount,
        IERC20 toCollateralToken,
        IERC20 loanToken,
        uint256 loanAmount,
        ISwapper swapper,
        bytes memory swapData
    ) external onlyOperator returns (SwapResult memory) {
        _morpho = address(morpho);
        _box = address(box);
        _slippageBefore = box.accumulatedSlippage();

        if (loanAmount == type(uint256).max) {
            loanAmount = fromFundingModule.debtBalance(fromFacilityData, loanToken);
        }
        if (fromCollateralAmount == type(uint256).max) {
            fromCollateralAmount = fromFundingModule.collateralBalance(fromFacilityData, fromCollateralToken);
        }

        morpho.flashLoan(
            address(loanToken),
            loanAmount,
            abi.encode(
                VaultV2Allocator.refinanceSwapCollateral.selector,
                address(box),
                fromFundingModule,
                fromFacilityData,
                toFundingModule,
                toFacilityData,
                fromCollateralToken,
                fromCollateralAmount,
                toCollateralToken,
                loanToken,
                loanAmount,
                swapper,
                swapData
            )
        );

        return SwapResult({
            expected: _expected,
            received: _received,
            slippageBefore: _slippageBefore,
            slippageAfter: box.accumulatedSlippage()
        });
    }

    /**
     * @notice Refinances to a new facility while swapping the loan asset.
     * @dev Flow: Flash loan new loan token -> Swap to old loan token -> Repay old debt
     *            -> Depledge collateral -> Pledge collateral to new facility
     *            -> Borrow new loan token to repay flash loan
     * @param morpho The Morpho protocol address for flash loans.
     * @param box The Box to perform operations on.
     * @param fromFundingModule The funding module to refinance from.
     * @param fromFacilityData The facility data for the source.
     * @param toFundingModule The funding module to refinance to.
     * @param toFacilityData The facility data for the destination.
     * @param collateralToken The collateral token (same for both facilities).
     * @param collateralAmount The amount of collateral (type(uint256).max for all).
     * @param fromLoanToken The original loan token.
     * @param fromLoanAmount The amount of original debt (type(uint256).max for all).
     * @param toLoanToken The new loan token.
     * @param toLoanAmount The amount of new loan token to flash loan.
     * @param swapper The swapper for loan token conversion.
     * @param swapData The swap data for the swapper.
     * @return result The swap result with expected, received, and slippage tracking.
     */
    function refinanceSwapLoan(
        IMorpho morpho,
        IBox box,
        IFunding fromFundingModule,
        bytes memory fromFacilityData,
        IFunding toFundingModule,
        bytes memory toFacilityData,
        IERC20 collateralToken,
        uint256 collateralAmount,
        IERC20 fromLoanToken,
        uint256 fromLoanAmount,
        IERC20 toLoanToken,
        uint256 toLoanAmount,
        ISwapper swapper,
        bytes memory swapData
    ) external onlyOperator returns (SwapResult memory) {
        _morpho = address(morpho);
        _box = address(box);
        _slippageBefore = box.accumulatedSlippage();

        if (fromLoanAmount == type(uint256).max) {
            fromLoanAmount = fromFundingModule.debtBalance(fromFacilityData, fromLoanToken);
        }
        if (collateralAmount == type(uint256).max) {
            collateralAmount = fromFundingModule.collateralBalance(fromFacilityData, collateralToken);
        }

        morpho.flashLoan(
            address(toLoanToken),
            toLoanAmount,
            abi.encode(
                VaultV2Allocator.refinanceSwapLoan.selector,
                address(box),
                fromFundingModule,
                fromFacilityData,
                toFundingModule,
                toFacilityData,
                collateralToken,
                collateralAmount,
                fromLoanToken,
                fromLoanAmount,
                toLoanToken,
                toLoanAmount,
                swapper,
                swapData
            )
        );

        return SwapResult({
            expected: _expected,
            received: _received,
            slippageBefore: _slippageBefore,
            slippageAfter: box.accumulatedSlippage()
        });
    }

    // =========================================================================
    //                        Flash Loan Callbacks
    // =========================================================================

    /**
     * @notice Morpho flash loan callback.
     * @dev Called by Morpho after flash loan funds are transferred.
     */
    function onMorphoFlashLoan(uint256 assets, bytes calldata data) external override {
        require(msg.sender == _morpho, ErrorsLib.OnlyMorpho());

        bytes4 operation = abi.decode(data, (bytes4));

        IBox box;
        IERC20 loanToken;

        if (operation == VaultV2Allocator.leverage.selector) {
            (, box, , , , loanToken, , , ) = abi.decode(data, (bytes4, IBox, IFunding, bytes, IERC20, IERC20, uint256, ISwapper, bytes));
        } else if (operation == VaultV2Allocator.deleverage.selector) {
            (, box, , , , , loanToken, , , ) = abi.decode(
                data,
                (bytes4, IBox, IFunding, bytes, IERC20, uint256, IERC20, uint256, ISwapper, bytes)
            );
        } else if (operation == VaultV2Allocator.refinance.selector) {
            (, box, , , , , , , loanToken, ) = abi.decode(
                data,
                (bytes4, IBox, IFunding, bytes, IFunding, bytes, IERC20, uint256, IERC20, uint256)
            );
        } else if (operation == VaultV2Allocator.refinanceSwapCollateral.selector) {
            (, box, , , , , , , , loanToken, , , ) = abi.decode(
                data,
                (bytes4, IBox, IFunding, bytes, IFunding, bytes, IERC20, uint256, IERC20, IERC20, uint256, ISwapper, bytes)
            );
        } else if (operation == VaultV2Allocator.refinanceSwapLoan.selector) {
            // For refinanceSwapLoan, we flash the NEW loan token (toLoanToken)
            (, box, , , , , , , , , loanToken, , , ) = abi.decode(
                data,
                (bytes4, IBox, IFunding, bytes, IFunding, bytes, IERC20, uint256, IERC20, uint256, IERC20, uint256, ISwapper, bytes)
            );
        } else {
            revert("VaultV2Allocator: Invalid operation");
        }

        // Approve the box to pull the flash loan amount
        loanToken.forceApprove(address(box), assets);

        // Call box.flash which will call back to us via onBoxFlash
        box.flash(loanToken, assets, data);

        // Repay the flash loan to Morpho
        loanToken.forceApprove(msg.sender, assets);
    }

    /**
     * @notice Box flash callback.
     * @dev Called by Box after flash funds are transferred. Executes the actual operation logic.
     */
    function onBoxFlash(IERC20, uint256, bytes calldata data) external override {
        require(msg.sender == _box, ErrorsLib.OnlyBox());

        bytes4 operation = abi.decode(data, (bytes4));
        IBox box = IBox(msg.sender);

        if (operation == VaultV2Allocator.leverage.selector) {
            _handleLeverage(box, data);
        } else if (operation == VaultV2Allocator.deleverage.selector) {
            _handleDeleverage(box, data);
        } else if (operation == VaultV2Allocator.refinance.selector) {
            _handleRefinance(box, data);
        } else if (operation == VaultV2Allocator.refinanceSwapCollateral.selector) {
            _handleRefinanceSwapCollateral(box, data);
        } else if (operation == VaultV2Allocator.refinanceSwapLoan.selector) {
            _handleRefinanceSwapLoan(box, data);
        } else {
            revert("VaultV2Allocator: Invalid operation");
        }
    }

    // =========================================================================
    //                     Internal Flash Loan Handlers
    // =========================================================================

    function _handleLeverage(IBox box, bytes calldata data) internal {
        (
            ,
            ,
            IFunding fundingModule,
            bytes memory facilityData,
            IERC20 collateralToken,
            IERC20 loanToken,
            uint256 loanAmount,
            ISwapper swapper,
            bytes memory swapData
        ) = abi.decode(data, (bytes4, IBox, IFunding, bytes, IERC20, IERC20, uint256, ISwapper, bytes));

        // Record collateral balance before swap
        uint256 beforeCollateral = collateralToken.balanceOf(address(box));

        // Swap loan tokens to collateral tokens
        _swap(box, swapper, swapData, loanToken, collateralToken, loanAmount);

        // Check how much collateral was received
        uint256 afterCollateral = collateralToken.balanceOf(address(box));
        uint256 collateralReceived = afterCollateral - beforeCollateral;

        // Pledge collateral to funding module
        box.pledge(fundingModule, facilityData, collateralToken, collateralReceived);

        // Borrow loan tokens to repay flash loan
        box.borrow(fundingModule, facilityData, loanToken, loanAmount);
    }

    function _handleDeleverage(IBox box, bytes calldata data) internal {
        (
            ,
            ,
            IFunding fundingModule,
            bytes memory facilityData,
            IERC20 collateralToken,
            uint256 collateralAmount,
            IERC20 loanToken,
            uint256 loanAmount,
            ISwapper swapper,
            bytes memory swapData
        ) = abi.decode(data, (bytes4, IBox, IFunding, bytes, IERC20, uint256, IERC20, uint256, ISwapper, bytes));

        // Repay debt with flash loaned tokens
        box.repay(fundingModule, facilityData, loanToken, loanAmount);

        // Withdraw collateral
        box.depledge(fundingModule, facilityData, collateralToken, collateralAmount);

        // Swap collateral to loan tokens to repay flash loan
        _swap(box, swapper, swapData, collateralToken, loanToken, collateralAmount);
    }

    function _handleRefinance(IBox box, bytes calldata data) internal {
        (
            ,
            ,
            IFunding fromFundingModule,
            bytes memory fromFacilityData,
            IFunding toFundingModule,
            bytes memory toFacilityData,
            IERC20 collateralToken,
            uint256 collateralAmount,
            IERC20 loanToken,
            uint256 loanAmount
        ) = abi.decode(data, (bytes4, IBox, IFunding, bytes, IFunding, bytes, IERC20, uint256, IERC20, uint256));

        // Repay old debt
        box.repay(fromFundingModule, fromFacilityData, loanToken, loanAmount);

        // Withdraw collateral from old facility
        box.depledge(fromFundingModule, fromFacilityData, collateralToken, collateralAmount);

        // Pledge collateral to new facility
        box.pledge(toFundingModule, toFacilityData, collateralToken, collateralAmount);

        // Borrow from new facility to repay flash loan
        box.borrow(toFundingModule, toFacilityData, loanToken, loanAmount);
    }

    function _handleRefinanceSwapCollateral(IBox box, bytes calldata data) internal {
        (
            ,
            ,
            IFunding fromFundingModule,
            bytes memory fromFacilityData,
            IFunding toFundingModule,
            bytes memory toFacilityData,
            IERC20 fromCollateralToken,
            uint256 fromCollateralAmount,
            IERC20 toCollateralToken,
            IERC20 loanToken,
            uint256 loanAmount,
            ISwapper swapper,
            bytes memory swapData
        ) = abi.decode(data, (bytes4, IBox, IFunding, bytes, IFunding, bytes, IERC20, uint256, IERC20, IERC20, uint256, ISwapper, bytes));

        // Repay old debt with flash loaned tokens
        box.repay(fromFundingModule, fromFacilityData, loanToken, loanAmount);

        // Withdraw old collateral
        box.depledge(fromFundingModule, fromFacilityData, fromCollateralToken, fromCollateralAmount);

        // Record new collateral balance before swap
        uint256 beforeNewCollateral = toCollateralToken.balanceOf(address(box));

        // Swap old collateral to new collateral
        _swap(box, swapper, swapData, fromCollateralToken, toCollateralToken, fromCollateralAmount);

        // Calculate how much new collateral was received
        uint256 afterNewCollateral = toCollateralToken.balanceOf(address(box));
        uint256 newCollateralReceived = afterNewCollateral - beforeNewCollateral;

        // Pledge new collateral to new facility
        box.pledge(toFundingModule, toFacilityData, toCollateralToken, newCollateralReceived);

        // Borrow from new facility to repay flash loan
        box.borrow(toFundingModule, toFacilityData, loanToken, loanAmount);
    }

    function _handleRefinanceSwapLoan(IBox box, bytes calldata data) internal {
        (
            ,
            ,
            IFunding fromFundingModule,
            bytes memory fromFacilityData,
            IFunding toFundingModule,
            bytes memory toFacilityData,
            IERC20 collateralToken,
            uint256 collateralAmount,
            IERC20 fromLoanToken,
            uint256 fromLoanAmount,
            IERC20 toLoanToken,
            uint256 toLoanAmount,
            ISwapper swapper,
            bytes memory swapData
        ) = abi.decode(
                data,
                (bytes4, IBox, IFunding, bytes, IFunding, bytes, IERC20, uint256, IERC20, uint256, IERC20, uint256, ISwapper, bytes)
            );

        // Record old loan token balance before swap
        uint256 beforeOldLoan = fromLoanToken.balanceOf(address(box));

        // Swap new loan token (from flash loan) to old loan token
        _swap(box, swapper, swapData, toLoanToken, fromLoanToken, toLoanAmount);

        // Calculate how much old loan token we received
        uint256 afterOldLoan = fromLoanToken.balanceOf(address(box));
        uint256 oldLoanReceived = afterOldLoan - beforeOldLoan;

        // Use whatever we received to repay (should be >= fromLoanAmount)
        uint256 repayAmount = oldLoanReceived > fromLoanAmount ? fromLoanAmount : oldLoanReceived;

        // Repay old debt
        box.repay(fromFundingModule, fromFacilityData, fromLoanToken, repayAmount);

        // Withdraw collateral from old facility
        box.depledge(fromFundingModule, fromFacilityData, collateralToken, collateralAmount);

        // Pledge collateral to new facility
        box.pledge(toFundingModule, toFacilityData, collateralToken, collateralAmount);

        // Borrow new loan token from new facility to repay flash loan
        box.borrow(toFundingModule, toFacilityData, toLoanToken, toLoanAmount);
    }

    // =========================================================================
    //                         Internal Helpers
    // =========================================================================

    /**
     * @dev Executes a swap via Box allocation functions based on token types.
     */
    function _swap(IBox box, ISwapper swapper, bytes memory swapData, IERC20 fromToken, IERC20 toToken, uint256 amount) internal {
        if (address(fromToken) == box.asset()) {
            (_expected, _received) = box.allocate(toToken, amount, swapper, swapData);
        } else if (address(toToken) == box.asset()) {
            (_expected, _received) = box.deallocate(fromToken, amount, swapper, swapData);
        } else {
            (_expected, _received) = box.reallocate(fromToken, toToken, amount, swapper, swapData);
        }
    }
}
